changes.sections/rich-text-block-2.liquid:
{%- assign heading = section.settings.heading -%}
{%- if heading == nil -%}{%- assign heading = 'Talk about your brand' -%}{%- endif -%}
{%- assign body = section.settings.body -%}
<div class="rich-text">
  {%- if heading != nil and heading != '' -%}
  <h2 class="rich-text__heading">{{ heading | escape }}</h2>
  {%- endif -%}
  {%- if body != nil and body != '' -%}
  <p class="rich-text__body">{{ body | escape }}</p>
  {%- endif -%}
</div>

{% schema %}
{
  "name": "Rich text",
  "settings": [
    { "type": "text", "id": "heading", "label": "Heading" },
    { "type": "textarea", "id": "body", "label": "Body" }
  ],
  "presets": [{ "name": "Rich text" }]
}
{% endschema %}

